# Health (HealthDCAT-AP, D6.2) atoms for the v3 merged reference set.
# A(...) fields: id, parent, statement, pr45 ids, claude v2 rows, stratum, status, modality, applicability,
# relation_to_base, rq2, flags, anchor (verbatim, checked against the source text), locator, overlaps, note, added.

def A(id, parent, statement, pr45=(), v2=(), stratum=None, status=None, modality=None, app=None, rel=None, rq2=None,
      flags=(), anchor=None, loc=None, overlaps=(), note='', added=False):
    return dict(id=id, parent=parent, statement=statement, pr45=list(pr45), v2=list(v2), stratum=stratum, status=status,
                modality=modality, app=app, rel=rel, rq2=rq2, flags=list(flags), anchor=anchor, loc=loc,
                overlaps=list(overlaps), note=note, added=added)

